import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { SkillName, Trigger } from '../types'
import { frontmatterDescription } from './frontmatter'
import { splitName, usageLine } from './labels'
import { badgeWidth, toRows } from './rows'
import { classifyTrigger, GLYPHS, triggerIcon, triggerLabel } from './triggers'

const PANE = 'skills-used'
const TITLE = 'Skills used'
const DESCRIPTION_LIMIT = 280

// Badge tints: translucent, so they sit on the panel in both light and dark themes.
// The border takes the fill's color: the desktop draws a round border, which rounds the badge.
const TINT = '#9a98902e'
const TINT_HOVER = '#9a989047'
const TINT_ACTIVE = '#5fa85f33'
const TINT_ACTIVE_HOVER = '#5fa85f4d'
const GREEN = '#7dba7d'
const MUTED = '#9a9890'
const HAIRLINE = '#9a989040'
const CARD = '#9a98901a'
const ICON_SIZE = 12

// Skills run in this session, in the order they were first used.
const used = atom({ plugin: 'skills-used', key: 'used' } as const, [] as SkillName[])
// Skills run in the reply that is being written right now.
const current = atom({ plugin: 'skills-used', key: 'current' } as const, [] as SkillName[])
// Each skill's description from its SKILL.md frontmatter.
const descriptions = atom(
  { plugin: 'skills-used', key: 'descriptions' } as const,
  {} as Record<SkillName, string>,
)
// Who started each skill the last time it ran.
const triggers = atom({ plugin: 'skills-used', key: 'triggers' } as const, {} as Record<SkillName, Trigger>)
// How many times each skill ran this session.
const counts = atom({ plugin: 'skills-used', key: 'counts' } as const, {} as Record<SkillName, number>)
// Replies finished so far, and the reply each skill last ran in: "2 replies ago" stays true without a timer.
const replies = atom({ plugin: 'skills-used', key: 'replies' } as const, 0)
const lastReply = atom({ plugin: 'skills-used', key: 'lastReply' } as const, {} as Record<SkillName, number>)

// Markers between events of one reply; a reload drops them.
let manualCommand: string | undefined
const pendingSkillCalls = new Map<SkillName, string>()

const addOnce = (name: SkillName) => (list: SkillName[]) =>
  list.includes(name) ? list : [...list, name]

const shorten = (text: string) => {
  const flat = text.replace(/\s+/g, ' ').trim()

  return flat.length > DESCRIPTION_LIMIT ? `${flat.slice(0, DESCRIPTION_LIMIT).trimEnd()}…` : flat
}

// Skills used before their description was recorded: read it from the skill's folder beside this one.
const tried = new Set<SkillName>()
async function fillMissing($: EngineInterface, list: SkillName[], known: Record<SkillName, string>) {
  for (const name of list) {
    if (known[name] !== undefined || tried.has(name) || name.includes(':')) {
      continue
    }
    tried.add(name)
    try {
      const description = frontmatterDescription(await $.fs.read(`${$.plugin.root}/../${name}/SKILL.md`))
      if (description !== undefined) {
        await update($, descriptions, all => ({ ...all, [name]: shorten(description) }))
      }
    } catch {
      // Not a skill of the user's skills folder: it stays without a description.
    }
  }
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'skills-used',
      description: 'Open the Skills used panel',
    })
    // An empty panel would only take room: it opens with the first skill, or now if this session has some.
    if ((await read($, used)).length > 0) {
      void $.ui.open({ id: PANE, title: TITLE }).catch(() => undefined)
    }

    return next(e)
  })

  // A slash command the person typed: a skill run this way is theirs.
  on('command.run', async ($, e, next) => {
    manualCommand = e.command.replace(/^\//, '')

    return next(e)
  })

  // A Skill call, from the main loop or a subagent, is pending until its skill has loaded.
  on('tool.call', { tool: 'Skill' }, async ($, e, next) => {
    pendingSkillCalls.set(e.skill, e.agentId ?? 'main')
    try {
      return await next(e)
    } finally {
      pendingSkillCalls.delete(e.skill)
    }
  })

  // Fires for /name typed by the person, the Skill tool, and skills preloaded into a subagent.
  on('skill.prompt', async ($, e, next) => {
    const trigger = classifyTrigger(e.skill, manualCommand, pendingSkillCalls.get(e.skill), await read($, current))
    if (trigger.kind === 'manual') {
      manualCommand = undefined
    }
    const isFirst = (await read($, used)).length === 0
    const reply = await read($, replies)
    await update($, triggers, all => ({ ...all, [e.skill]: trigger }))
    await update($, counts, all => ({ ...all, [e.skill]: (all[e.skill] ?? 0) + 1 }))
    await update($, lastReply, all => ({ ...all, [e.skill]: reply }))
    await update($, used, addOnce(e.skill))
    await update($, current, addOnce(e.skill))
    if (isFirst) {
      void $.ui.open({ id: PANE, title: TITLE }).catch(() => undefined)
    }

    const description = e.frontmatter.description
    if (typeof description === 'string' && description.trim() !== '') {
      await update($, descriptions, all => ({ ...all, [e.skill]: shorten(description) }))
    }

    return next(e)
  })

  // The main loop's reply is done: nothing is in use any more.
  on('turn.complete', async ($, e, next) => {
    if (e.agentId === undefined) {
      manualCommand = undefined
      await update($, current, () => [])
      await update($, replies, n => n + 1)
    }

    return next(e)
  })

  on('session.end', async ($, e, next) => {
    if (e.reason === 'clear') {
      await update($, used, () => [])
      await update($, current, () => [])
      await update($, triggers, () => ({}))
      await update($, counts, () => ({}))
      await update($, lastReply, () => ({}))
      await update($, replies, () => 0)
    }

    return next(e)
  })

  on('command.run', { command: 'skills-used' }, async $ => {
    const opened = await $.ui.open({ id: PANE, title: TITLE })

    return { text: opened.isPlaced ? 'Skills used panel opened.' : 'The panel did not fit on screen.' }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const elements = $.ui.resolve(e)
    const { Box, Text } = elements
    const list = await read($, used)
    const active = await read($, current)
    const about = await read($, descriptions)
    const startedBy = await read($, triggers)
    const runs = await read($, counts)
    const replyNow = await read($, replies)
    const lastIn = await read($, lastReply)
    void fillMissing($, list, about)

    // The trigger's icon: an Svg where the surface draws one, a glyph elsewhere.
    const icon = (name: SkillName, isActive: boolean) => {
      const trigger = startedBy[name]
      if (trigger === undefined) {
        return null
      }
      const color = isActive ? GREEN : MUTED
      if (e.surface === 'desktop' && 'Svg' in elements) {
        const { Svg } = elements

        return (
          <Svg
            source={triggerIcon(trigger.kind, color)}
            alt={triggerLabel(trigger)}
            width={ICON_SIZE}
            height={ICON_SIZE}
          />
        )
      }

      return (
        <Text size="footnote" color={color}>
          {GLYPHS[trigger.kind]}
        </Text>
      )
    }

    if (list.length === 0) {
      return (
        <Text size="footnote" dimColor>
          No skills used yet.
        </Text>
      )
    }

    const scopeOf = (name: SkillName) => `tile-${list.indexOf(name)}`

    const badge = (name: SkillName) => {
      const isActive = active.includes(name)
      const fill = isActive ? TINT_ACTIVE : TINT
      const hoverFill = isActive ? TINT_ACTIVE_HOVER : TINT_HOVER
      const { plugin, skill } = splitName(name)
      const count = runs[name] ?? 1

      return (
        <Box
          key={name}
          borderStyle="round"
          borderColor={fill}
          backgroundColor={fill}
          paddingX={1}
          flexDirection="row"
          alignItems="center"
          gap="xs"
          hover={{ scope: scopeOf(name), borderColor: hoverFill, backgroundColor: hoverFill }}
        >
          {plugin !== undefined && (
            <Text size="caption" color={MUTED}>
              {plugin}
            </Text>
          )}
          {isActive ? (
            <Text size="footnote" color={GREEN}>
              {skill}
            </Text>
          ) : (
            <Text size="footnote" dimColor>
              {skill}
            </Text>
          )}
          {count > 1 && (
            <Text size="caption" color={isActive ? GREEN : MUTED}>
              ×{count}
            </Text>
          )}
          {icon(name, isActive)}
        </Box>
      )
    }

    // The hovered badge's description: hidden until its badge is under the pointer.
    const card = (name: SkillName) => (
      <Box
        key={`about-${name}`}
        display="none"
        hover={{ scope: scopeOf(name), display: 'flex' }}
        flexDirection="column"
        borderStyle="round"
        borderColor={HAIRLINE}
        backgroundColor={CARD}
        paddingX={1}
      >
        <Text size="footnote" weight="medium">
          {name}
        </Text>
        {startedBy[name] !== undefined && (
          <Text size="caption" dimColor>
            {triggerLabel(startedBy[name])}
          </Text>
        )}
        {lastIn[name] !== undefined && (
          <Text size="caption" dimColor>
            {usageLine(runs[name] ?? 1, active.includes(name) ? 0 : replyNow - lastIn[name])}
          </Text>
        )}
        <Box marginTop="xs">
          <Text size="footnote" dimColor wrap="wrap">
            {about[name] ?? 'No description.'}
          </Text>
        </Box>
      </Box>
    )

    // Each row's cards sit right under it: a description opens beside its badge, and the rows below move down.
    return (
      <Box flexDirection="column" gap="xs">
        {toRows(list, Math.max(20, e.props.bodyColumns), name => badgeWidth(name) + ((runs[name] ?? 1) > 1 ? 3 : 0)).map(row => (
          <Box key={`row-${row[0]}`} flexDirection="column" gap="xs">
            <Box flexDirection="row" flexWrap="wrap" gap="xs">
              {row.map(badge)}
            </Box>
            {row.map(card)}
          </Box>
        ))}
      </Box>
    )
  })
}

