// The `description` of a SKILL.md frontmatter: inline, quoted, or a `|` / `>` block.
export const frontmatterDescription = (file: string): string | undefined => {
  const head = /^---\r?\n([\s\S]*?)\r?\n---/.exec(file)?.[1]
  if (head === undefined) {
    return undefined
  }
  const lines = head.split(/\r?\n/)
  const at = lines.findIndex(line => /^description:/.test(line))
  if (at === -1) {
    return undefined
  }
  const inline = (lines[at] ?? '').slice('description:'.length).trim()
  if (inline !== '' && !/^[|>][-+]?$/.test(inline)) {
    return inline.replace(/^(['"])([\s\S]*)\1$/, '$2')
  }
  const block: string[] = []
  for (const line of lines.slice(at + 1)) {
    if (line.trim() !== '' && !/^\s/.test(line)) {
      break
    }
    block.push(line.trim())
  }
  const text = block.join(' ').trim()

  return text === '' ? undefined : text
}

