import type { SkillName } from '../types'

// A plugin skill's name in two parts, so the badge can dim the plugin: `engineering:standup`.
export const splitName = (name: SkillName): { plugin?: string; skill: string } => {
  const at = name.lastIndexOf(':')

  return at > 0 && at < name.length - 1 ? { plugin: name.slice(0, at), skill: name.slice(at + 1) } : { skill: name }
}

// How often a skill ran, and in which reply it last did.
export const usageLine = (count: number, repliesAgo: number) => {
  const times = count === 1 ? 'Used once' : `Used ${count} times`
  const when =
    repliesAgo <= 0
      ? 'last in this reply'
      : repliesAgo === 1
        ? 'last in the previous reply'
        : `last ${repliesAgo} replies ago`

  return `${times} · ${when}`
}

