import type { SkillName } from '../types'

// A badge's width in cells, rounded up: one cell per character, plus padding, border, icon and the gap after it.
export const badgeWidth = (name: SkillName) => name.length + 7

// Badges in rows that fit the panel, so a hovered badge's description can open right under its row.
// A badge wider than the panel gets a row of its own.
export const toRows = (
  names: SkillName[],
  columns: number,
  widthOf: (name: SkillName) => number = badgeWidth,
): SkillName[][] => {
  const rows: SkillName[][] = []
  let row: SkillName[] = []
  let used = 0
  for (const name of names) {
    const width = widthOf(name)
    if (row.length > 0 && used + width > columns) {
      rows.push(row)
      row = []
      used = 0
    }
    row.push(name)
    used += width
  }
  if (row.length > 0) {
    rows.push(row)
  }

  return rows
}

