import type { SkillName, Trigger } from '../types'

// Outline icons from Tabler Icons (MIT), 24×24, stroked in the given color.
const PATHS: Record<Trigger['kind'], string> = {
  manual:
    '<path d="M8 7a4 4 0 1 0 8 0a4 4 0 0 0 -8 0"/><path d="M6 21v-2a4 4 0 0 1 4 -4h4a4 4 0 0 1 4 4v2"/>',
  model:
    '<path d="M16 18a2 2 0 0 1 2 2a2 2 0 0 1 2 -2a2 2 0 0 1 -2 -2a2 2 0 0 1 -2 2zm0 -12a2 2 0 0 1 2 2a2 2 0 0 1 2 -2a2 2 0 0 1 -2 -2a2 2 0 0 1 -2 2zm-7 12a6 6 0 0 1 6 -6a6 6 0 0 1 -6 -6a6 6 0 0 1 -6 6a6 6 0 0 1 6 6z"/>',
  chained:
    '<path d="M9 15l6 -6"/><path d="M11 6l.463 -.536a5 5 0 0 1 7.071 7.072l-.534 .464"/><path d="M13 18l-.397 .534a5.068 5.068 0 0 1 -7.127 0a4.972 4.972 0 0 1 0 -7.071l.524 -.463"/>',
  subagent:
    '<path d="M6 6a2 2 0 0 1 2 -2h8a2 2 0 0 1 2 2v4a2 2 0 0 1 -2 2h-8a2 2 0 0 1 -2 -2z"/><path d="M12 2v2"/><path d="M9 12v9"/><path d="M15 12v9"/><path d="M5 16l4 -2"/><path d="M15 14l4 2"/><path d="M9 18h6"/><path d="M10 8v.01"/><path d="M14 8v.01"/>',
}

// Stand-ins where a surface draws no Svg.
export const GLYPHS: Record<Trigger['kind'], string> = {
  manual: '/',
  model: '✦',
  chained: '↳',
  subagent: '◇',
}

export const triggerIcon = (kind: Trigger['kind'], color: string) =>
  `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="${color}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${PATHS[kind]}</svg>`

export const triggerLabel = (trigger: Trigger) => {
  switch (trigger.kind) {
    case 'manual':
      return 'Started by you'
    case 'model':
      return 'Started by Claude'
    case 'chained':
      return `Chained after ${trigger.after}`
    case 'subagent':
      return 'Started in a subagent'
  }
}

// Who started a skill: a typed /name, a Skill call of the main loop or a subagent, or a preload.
// The four kinds follow madolphe/skill-trace (MIT).
export const classifyTrigger = (
  skill: SkillName,
  manualCommand: string | undefined,
  pendingAgent: string | undefined,
  activeInReply: SkillName[],
): Trigger => {
  if (manualCommand === skill) {
    return { kind: 'manual' }
  }
  if (pendingAgent === undefined) {
    // No Skill call to answer for it: preloaded into a subagent as it spawned.
    return { kind: 'subagent' }
  }
  if (pendingAgent !== 'main') {
    return { kind: 'subagent' }
  }
  const before = activeInReply.filter(name => name !== skill).at(-1)

  return before === undefined ? { kind: 'model' } : { kind: 'chained', after: before }
}

