export type SkillName = string

export type Trigger =
  | { kind: 'manual' }
  | { kind: 'model' }
  | { kind: 'chained'; after: SkillName }
  | { kind: 'subagent' }

declare module 'claude-code' {
  interface PluginState {
    'skills-used': {
      used: SkillName[]
      current: SkillName[]
      descriptions: Record<SkillName, string>
      triggers: Record<SkillName, Trigger>
      counts: Record<SkillName, number>
      replies: number
      lastReply: Record<SkillName, number>
    }
  }
}
